const DEFAULT_WORKFLOW = "name: Vueling · MFE Viajes\n\non:\n  schedule:\n    - cron: '40 6 * * *'\n      timezone: \"Europe/Madrid\"\n  workflow_dispatch:\n    inputs:\n      force:\n        description: \"Forzar comprobación\"\n        required: false\n        default: \"true\"\n      telegram_test:\n        description: \"Solo probar Telegram\"\n        required: false\n        default: \"false\"\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: vueling-monitor\n  cancel-in-progress: false\n\njobs:\n  monitor:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    defaults:\n      run:\n        working-directory: monitoring\n    env:\n      MFE_VUELING_WORKER_URL: ${{ secrets.MFE_VUELING_WORKER_URL }}\n      MFE_VUELING_MONITOR_SECRET: ${{ secrets.MFE_VUELING_MONITOR_SECRET }}\n      TELEGRAM_BOT_TOKEN: ${{ secrets.TELEGRAM_BOT_TOKEN }}\n      TELEGRAM_CHAT_ID: ${{ secrets.TELEGRAM_CHAT_ID }}\n      MFE_FORCE_RUN: ${{ github.event_name == 'workflow_dispatch' && inputs.force || 'false' }}\n      MFE_TEST_TELEGRAM: ${{ github.event_name == 'workflow_dispatch' && inputs.telegram_test || 'false' }}\n      PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD: '1'\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: '22'\n          cache: npm\n          cache-dependency-path: monitoring/package-lock.json\n      - name: Instalar dependencias Node\n        run: npm ci\n      - name: Comprobar Chrome preinstalado\n        shell: bash\n        run: |\n          set -e\n          if command -v google-chrome >/dev/null 2>&1; then\n            google-chrome --version\n          elif command -v google-chrome-stable >/dev/null 2>&1; then\n            google-chrome-stable --version\n          else\n            echo \"::error::El runner no tiene Google Chrome preinstalado.\"\n            exit 1\n          fi\n      - name: Ejecutar monitor Vueling\n        run: node vueling.mjs\n      - name: Guardar diagnóstico siempre\n        if: always()\n        uses: actions/upload-artifact@v4\n        with:\n          name: vueling-diagnostico-${{ github.run_number }}\n          path: monitoring/artifacts/vueling/\n          if-no-files-found: ignore\n          retention-days: 7\n";
const VUELING_SCRIPT_PATH="monitoring/vueling.mjs";
const VUELING_CONFIG_PATH="monitoring/vueling-config.json";
