async function readPayload(request){if(request.method==='GET'){const u=new URL(request.url);return {action:u.searchParams.get('action')||'',type:u.searchParams.get('type')||''};}if(request.method!=='POST')throw new ApiError(405,'Método no permitido.');let body;try{body=await request.json();}catch{throw new ApiError(400,'El cuerpo debe ser JSON válido.');}return {action:String(body?.action||'').trim(),type:String(body?.type||'').trim(),result:body?.result||null,config:body?.config||{},force:Boolean(body?.force),mode:String(body?.mode||'').trim(),telegramTest:Boolean(body?.telegramTest)};}
function githubHeaders(env){const token=String(env?.GITHUB_TOKEN||'').trim();if(!token)throw new ApiError(503,'GITHUB_TOKEN no está configurado.');return {Authorization:`Bearer ${token}`,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','User-Agent':'MFE-Viajes-Vueling/1.0.0','Content-Type':'application/json'};}
