async function githubRaw(url,options,env){return fetch(url,{...options,headers:{...githubHeaders(env),...(options?.headers||{})}});}
async function githubApiError(response,data){const raw=String(data?.message||`GitHub respondió HTTP ${response.status}`);if(response.status===401||/bad credentials/i.test(raw))return new ApiError(401,'GitHub ha rechazado GITHUB_TOKEN del Worker Vueling: credenciales no válidas. El token puede haber caducado o sido revocado. Renueva GITHUB_TOKEN en mfe-viajes-vueling.');if(response.status===403&&/resource not accessible|forbidden|permission/i.test(raw))return new ApiError(403,'GitHub ha aceptado el token del Worker Vueling, pero no tiene permisos suficientes para Contents/Actions en autoreisen-monitor.');return new ApiError(response.status===404?502:response.status,raw);}async function githubJson(url,options,env){const r=await githubRaw(url,options,env);if(r.status===204)return {};let d=null;try{d=await r.json();}catch{}if(!r.ok)throw githubApiError(r,d);return d||{};}
async function remoteFile(target,path,env){const encoded=path.split('/').map(encodeURIComponent).join('/'),url=`https://api.github.com/repos/${encodeURIComponent(target.owner)}/${encodeURIComponent(target.repo)}/contents/${encoded}?ref=${encodeURIComponent(target.branch)}`;const r=await githubRaw(url,{method:'GET'},env);if(r.status===404)return {exists:false,content:'',sha:''};if(!r.ok){let d=null;try{d=await r.json();}catch{}throw githubApiError(r,d||{message:`GitHub no pudo leer ${path} (HTTP ${r.status}).`});}const d=await r.json();return {exists:true,content:decodeContent(d.content||''),sha:String(d.sha||'')};}
