function normalizeText(v){return String(v||'').replace(/\r\n/g,'\n').replace(/\n?$/,'\n');}
function cleanConfig(input={}){const allowed=['enabled','origin','destination','departureDate','returnDate','outboundFlight','returnFlight','outboundTime','returnTime','directOnly','adults','children','infants','fare','underseatBag','sameHandBaggageAllPassengers','checkedBags','checkedBagKg','checkedBagCount','checkedBagPassenger','sameBaggageRoundTrip','sameBaggageAllPassengers','contactFirstName','contactLastName','email','country','phonePrefix','phone','passenger1FirstName','passenger1LastName','passenger2FirstName','passenger2LastName','passenger3FirstName','passenger3LastName','passenger4FirstName','passenger4LastName','passenger5FirstName','passenger5LastName','marketingConsent','reservedPrice','telegramEnabled','telegramNotifyEveryCheck','telegramNotifyPriceDrop','scheduleTime','scheduleTimeZone','title','color','gradient1','gradient2'];const c={};for(const k of allowed)if(input[k]!==undefined)c[k]=input[k];for(const k of ['origin','destination'])c[k]=String(c[k]||'').toUpperCase().trim();for(const k of ['outboundFlight','returnFlight'])c[k]=String(c[k]||'').toUpperCase().trim();if(!/^[A-Z]{3}$/.test(c.origin)||!/^[A-Z]{3}$/.test(c.destination))throw new ApiError(400,'Los aeropuertos deben ser IATA de 3 letras.');if(!/^\d{4}-\d{2}-\d{2}$/.test(String(c.departureDate||''))||!/^\d{4}-\d{2}-\d{2}$/.test(String(c.returnDate||'')))throw new ApiError(400,'Fechas Vueling no válidas.');c.adults=Math.max(1,Math.min(5,Number(c.adults)||1));c.children=Math.max(0,Math.min(4,Number(c.children)||0));c.infants=Math.max(0,Math.min(4,Number(c.infants)||0));if(c.adults+c.children+c.infants>5)throw new ApiError(400,'El seguimiento Vueling admite un máximo de 5 pasajeros.');const seated=Math.max(1,c.adults+c.children);const weights=[15,20,25,30];let bags=Array.isArray(c.checkedBags)?c.checkedBags:[];if(!bags.length){const legacyKg=weights.includes(Number(c.checkedBagKg))?Number(c.checkedBagKg):25,legacyCount=Math.max(0,Math.min(3,Number(c.checkedBagCount)||0)),legacyPassenger=Math.max(1,Math.min(seated,Number(c.checkedBagPassenger)||1));bags=Array.from({length:legacyCount},()=>({kg:legacyKg,passenger:legacyPassenger,outbound:true,return:c.sameBaggageRoundTrip!==false}));}c.checkedBags=bags.slice(0,3).map(item=>({kg:weights.includes(Number(item?.kg))?Number(item.kg):25,passenger:Math.max(1,Math.min(seated,Number(item?.passenger)||1)),outbound:item?.outbound!==false,return:item?.return!==false})).filter(item=>item.outbound||item.return);const firstBag=c.checkedBags[0];c.checkedBagKg=firstBag?.kg||25;c.checkedBagCount=c.checkedBags.length;c.checkedBagPassenger=firstBag?.passenger||1;c.sameBaggageRoundTrip=Boolean(firstBag&&c.checkedBags.every(b=>b.outbound&&b.return));c.sameBaggageAllPassengers=false;c.reservedPrice=Math.max(0,Number(c.reservedPrice)||0);c.enabled=c.enabled!==false;c.directOnly=c.directOnly!==false;c.underseatBag=c.underseatBag!==false;c.sameHandBaggageAllPassengers=c.sameHandBaggageAllPassengers!==false;c.marketingConsent=Boolean(c.marketingConsent);c.telegramEnabled=c.telegramEnabled!==false;c.telegramNotifyEveryCheck=c.telegramNotifyEveryCheck!==false;c.telegramNotifyPriceDrop=c.telegramNotifyPriceDrop!==false;c.fare=String(c.fare||'FLY LIGHT').trim();c.country=String(c.country||'España').trim();c.scheduleTime=String(c.scheduleTime||'06:40').trim();c.scheduleTimeZone='Europe/Madrid';return c;}
function workflowForConfig(config){const [hh='06',mm='40']=String(config.scheduleTime||'06:40').split(':'),hour=Math.max(0,Math.min(23,Number(hh)||0)),minute=Math.max(0,Math.min(59,Number(mm)||0));return DEFAULT_WORKFLOW.replace("    - cron: '40 6 * * *'",`    - cron: '${minute} ${hour} * * *'`);}
async function readConfig(target,env){const r=await remoteFile(target,VUELING_CONFIG_PATH,env);if(!r.exists)return {vueling:JSON.parse(DEFAULT_CONFIG_FILE).vueling};try{return JSON.parse(r.content);}catch{return {vueling:JSON.parse(DEFAULT_CONFIG_FILE).vueling};}}
async function syncConfig(request,env,payload){const user=await verifyFirebaseUser(request,env),target=githubTarget(env),cfg=cleanConfig(payload.config||{}),doc=await readConfig(target,env);doc.vueling={...(doc.vueling||{}),...cfg};await upsertFile(target,VUELING_CONFIG_PATH,JSON.stringify(doc,null,2)+'\n',env,'Sincronizar configuración Vueling · MFE Viajes');await upsertFile(target,VUELING_WORKFLOW_PATH,workflowForConfig(doc.vueling),env,'Actualizar horario workflow Vueling');return jsonResponse({ok:true,synced:true,updatedAt:new Date().toISOString(),authorizedUid:user.sub});}
