async function ensureInstalled(target,env,config){const st=await inspect(target,env);if(st.installed)return st;await upsertFile(target,VUELING_SCRIPT_PATH,VUELING_FILE,env,'Reparar monitor Vueling · MFE Viajes v1.0.23');if(!st.files.config)await upsertFile(target,VUELING_CONFIG_PATH,DEFAULT_CONFIG_FILE,env,'Crear configuración Vueling');await upsertFile(target,VUELING_WORKFLOW_PATH,workflowForConfig(config||JSON.parse(DEFAULT_CONFIG_FILE).vueling),env,'Reparar workflow Vueling');const verified=await inspect(target,env);if(!verified.installed)throw new ApiError(502,'No se pudo reparar la automatización Vueling.');return verified;}
async function dispatch(target,env,{force=true,telegramTest=false}={}){const url=`https://api.github.com/repos/${encodeURIComponent(target.owner)}/${encodeURIComponent(target.repo)}/actions/workflows/${encodeURIComponent('vueling-monitor.yml')}/dispatches`;await githubJson(url,{method:'POST',body:JSON.stringify({ref:target.branch,inputs:{force:String(Boolean(force)),telegram_test:String(Boolean(telegramTest))}})},env);}
async function run(request,env,payload){const user=await verifyFirebaseUser(request,env),target=githubTarget(env),doc=await readConfig(target,env),cfg=cleanConfig(payload.config&&Object.keys(payload.config).length?payload.config:doc.vueling||JSON.parse(DEFAULT_CONFIG_FILE).vueling);if(payload.config&&Object.keys(payload.config).length){doc.vueling={...(doc.vueling||{}),...cfg};await upsertFile(target,VUELING_CONFIG_PATH,JSON.stringify(doc,null,2)+'\n',env,'Sincronizar Vueling antes de ejecutar');await upsertFile(target,VUELING_WORKFLOW_PATH,workflowForConfig(doc.vueling),env,'Actualizar horario Vueling');}await ensureInstalled(target,env,cfg);await dispatch(target,env,{force:payload.force!==false,telegramTest:payload.mode==='telegram-test'||payload.telegramTest});return jsonResponse({ok:true,workflowTriggered:true,repository:`${target.owner}/${target.repo}`,authorizedUid:user.sub,updatedAt:new Date().toISOString()});}
async function status(request,env){const user=await verifyFirebaseUser(request,env),target=githubTarget(env),st=await inspect(target,env);return jsonResponse({ok:true,...st,expectedAutomationVersion:AUTOMATION_VERSION,repository:`${target.owner}/${target.repo}`,branch:target.branch,authorizedUid:user.sub,checkedAt:new Date().toISOString()});}
async function githubDiagnostic(request,env){const user=await verifyFirebaseUser(request,env),target=githubTarget(env);const repo=await githubJson(`https://api.github.com/repos/${encodeURIComponent(target.owner)}/${encodeURIComponent(target.repo)}`,{method:'GET'},env);const workflows=await githubJson(`https://api.github.com/repos/${encodeURIComponent(target.owner)}/${encodeURIComponent(target.repo)}/actions/workflows?per_page=100`,{method:'GET'},env);return jsonResponse({ok:true,githubAuth:true,repository:`${target.owner}/${target.repo}`,private:Boolean(repo?.private),defaultBranch:String(repo?.default_branch||target.branch),actionsReadable:Array.isArray(workflows?.workflows),workflowCount:Number(workflows?.total_count)||0,workerVersion:WORKER_VERSION,checkedAt:new Date().toISOString(),authorizedUid:user.sub});}
export default {async fetch(request,env){if(request.method==='OPTIONS')return new Response(null,{status:204,headers:CORS_HEADERS});try{const payload=await readPayload(request);if(payload.action==='health'||payload.action==='integration-health'||(!payload.action&&request.method==='GET'))return jsonResponse({ok:true,service:'MFE Viajes · Vueling Worker',version:WORKER_VERSION,automationVersion:AUTOMATION_VERSION,githubConfigured:Boolean(env?.GITHUB_TOKEN&&env?.GITHUB_OWNER&&env?.GITHUB_REPO),firebaseAuthConfigured:Boolean(env?.FIREBASE_PROJECT_ID),kvConfigured:Boolean(env?.MFE_TRACKERS)});if(payload.action==='vueling'){const result=await readLatest(env);return result?jsonResponse({ok:true,result}):jsonResponse({ok:false,error:'Todavía no hay resultados Vueling.'},404);}if(payload.action==='monitor-history'){let history=[];try{history=JSON.parse(await requireKv(env).get(historyKey())||'[]');}catch{}return jsonResponse({ok:true,results:history});}if(payload.action==='monitor-write')return await writeResult(request,env,payload);if(payload.action==='github-vueling-sync')return await syncConfig(request,env,payload);if(payload.action==='github-vueling-install')return await install(request,env,payload);if(payload.action==='github-vueling-run')return await run(request,env,payload);if(payload.action==='github-vueling-status')return await status(request,env);if(payload.action==='github-vueling-diagnostic')return await githubDiagnostic(request,env);throw new ApiError(400,'Acción Vueling no reconocida.');}catch(error){return jsonResponse({ok:false,error:error?.message||'Error interno del Worker Vueling.'},error instanceof ApiError?error.status:500);}}};
